/**
 * Form builder data model (SPEC §10.1). Form definitions live inline in block
 * content (Contact, Booking intake, custom forms) so they are versioned with
 * the draft/published site and can be generated by templates and the AI.
 * Isomorphic.
 */
import { z } from 'zod'
import { idSchema, localizedSchema, type Localized } from './fields'

export const FORM_FIELD_TYPES = [
  'text',
  'email',
  'phone',
  'textarea',
  'select',
  'radio',
  'checkbox',
  'date',
  'file', // Pro, max 10 MB
  'budget',
] as const
export type FormFieldType = (typeof FORM_FIELD_TYPES)[number]

export const MAX_FORM_FIELDS = 20
export const MAX_FILE_UPLOAD_BYTES = 10 * 1024 * 1024

export const formOptionSchema = z.object({
  value: z.string().min(1).max(100),
  label: localizedSchema,
})

export const formFieldSchema = z.object({
  id: idSchema,
  type: z.enum(FORM_FIELD_TYPES),
  label: localizedSchema,
  placeholder: localizedSchema.optional(),
  help: localizedSchema.optional(),
  required: z.boolean(),
  /** select, radio, budget (ranges). */
  options: z.array(formOptionSchema).max(30).optional(),
  /** Half-width on desktop when true. */
  half: z.boolean().optional(),
})
export type FormField = z.infer<typeof formFieldSchema>

export const formSettingsSchema = z.object({
  submitLabel: localizedSchema,
  afterSubmit: z.object({
    type: z.enum(['message', 'redirect']),
    message: localizedSchema.optional(),
    redirectUrl: z.string().max(2000).optional(),
  }),
  /** Optional auto-reply email sent to the visitor (needs an email field). */
  autoReply: z
    .object({
      enabled: z.boolean(),
      subject: localizedSchema.optional(),
      body: localizedSchema.optional(),
    })
    .optional(),
  /** Email the site owner on each submission. */
  notifyOwner: z.boolean(),
})
export type FormSettings = z.infer<typeof formSettingsSchema>

export const formDefinitionSchema = z.object({
  name: z.string().max(120),
  fields: z.array(formFieldSchema).min(1).max(MAX_FORM_FIELDS),
  settings: formSettingsSchema,
})
export type FormDefinition = z.infer<typeof formDefinitionSchema>

const L = (en: string, ar: string): Localized => ({ en, ar })

/** The default contact form used by new Contact blocks. */
export function defaultContactForm(): FormDefinition {
  return {
    name: 'Contact',
    fields: [
      { id: 'name', type: 'text', label: L('Name', 'الاسم'), placeholder: L('Your name', 'اسمك'), required: true, half: true },
      {
        id: 'email',
        type: 'email',
        label: L('Email', 'البريد الإلكتروني'),
        placeholder: L('you@example.com', 'you@example.com'),
        required: true,
        half: true,
      },
      {
        id: 'message',
        type: 'textarea',
        label: L('Message', 'الرسالة'),
        placeholder: L('How can I help?', 'كيف يمكنني مساعدتك؟'),
        required: true,
      },
    ],
    settings: {
      submitLabel: L('Send message', 'إرسال الرسالة'),
      afterSubmit: {
        type: 'message',
        message: L('Thank you — your message is on its way.', 'شكرًا لك — رسالتك في الطريق.'),
      },
      notifyOwner: true,
    },
  }
}

/**
 * Build a Zod schema that validates a submission against a form definition.
 * Used by the public submit endpoint and by the client form for instant feedback.
 */
export function submissionSchemaFor(form: Pick<FormDefinition, 'fields'>) {
  const shape: Record<string, z.ZodType> = {}
  for (const field of form.fields) {
    let s: z.ZodType
    switch (field.type) {
      case 'email':
        s = z.email().max(320)
        break
      case 'phone':
        s = z
          .string()
          .max(40)
          .regex(/^\+?[0-9 ()\-.]{5,}$/, 'Invalid phone number')
        break
      case 'checkbox':
        s = field.required ? z.literal(true) : z.boolean()
        break
      case 'date':
        s = z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Invalid date')
        break
      case 'select':
      case 'radio':
      case 'budget': {
        const values = (field.options ?? []).map((o) => o.value)
        s = values.length > 0 ? z.enum(values as [string, ...string[]]) : z.string().max(200)
        break
      }
      case 'file':
        // The upload endpoint returns a file reference; the submission carries it.
        s = z.object({ url: z.string().max(2000), name: z.string().max(300), bytes: z.number().int().nonnegative() })
        break
      case 'textarea':
        s = z.string().max(5000)
        break
      default:
        s = z.string().max(500)
    }
    if (field.type !== 'checkbox') {
      if (field.required) {
        if (field.type === 'text' || field.type === 'textarea') s = (s as z.ZodString).min(1, 'Required')
      } else {
        s = z.union([s, z.literal('')]).optional()
      }
    }
    shape[field.id] = s
  }
  return z.object(shape)
}
